module axixclk #(
		parameter integer C_S_AXI_ID_WIDTH	= 2,
		parameter integer C_S_AXI_DATA_WIDTH	= 32,
		parameter integer C_S_AXI_ADDR_WIDTH	= 6,
		parameter [0:0]	OPT_WRITE_ONLY = 1'b0,
		parameter [0:0]	OPT_READ_ONLY = 1'b0,
		parameter	XCLOCK_FFS = 2,
		parameter	LGFIFO = 5
	) (
		input	wire				S_AXI_ACLK,
		input	wire				S_AXI_ARESETN,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_AWID,
		input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_AWADDR,
		input	wire [7 : 0]			S_AXI_AWLEN,
		input	wire [2 : 0]			S_AXI_AWSIZE,
		input	wire [1 : 0]			S_AXI_AWBURST,
		input	wire				S_AXI_AWLOCK,
		input	wire [3 : 0]			S_AXI_AWCACHE,
		input	wire [2 : 0]			S_AXI_AWPROT,
		input	wire [3 : 0]			S_AXI_AWQOS,
		input	wire				S_AXI_AWVALID,
		output	wire				S_AXI_AWREADY,
		input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_WDATA,
		input	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] S_AXI_WSTRB,
		input	wire				S_AXI_WLAST,
		input	wire				S_AXI_WVALID,
		output	wire				S_AXI_WREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_BID,
		output	wire [1 : 0]			S_AXI_BRESP,
		output	wire				S_AXI_BVALID,
		input	wire				S_AXI_BREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_ARID,
		input	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	S_AXI_ARADDR,
		input	wire [7 : 0]			S_AXI_ARLEN,
		input	wire [2 : 0]			S_AXI_ARSIZE,
		input	wire [1 : 0]			S_AXI_ARBURST,
		input	wire				S_AXI_ARLOCK,
		input	wire [3 : 0]			S_AXI_ARCACHE,
		input	wire [2 : 0]			S_AXI_ARPROT,
		input	wire [3 : 0]			S_AXI_ARQOS,
		input	wire				S_AXI_ARVALID,
		output	wire				S_AXI_ARREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	S_AXI_RID,
		output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	S_AXI_RDATA,
		output	wire [1 : 0]			S_AXI_RRESP,
		output	wire				S_AXI_RLAST,
		output	wire				S_AXI_RVALID,
		input	wire				S_AXI_RREADY,
		input	wire				M_AXI_ACLK,
		output	wire				M_AXI_ARESETN,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_AWID,
		output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_AWADDR,
		output	wire [7 : 0]			M_AXI_AWLEN,
		output	wire [2 : 0]			M_AXI_AWSIZE,
		output	wire [1 : 0]			M_AXI_AWBURST,
		output	wire				M_AXI_AWLOCK,
		output	wire [3 : 0]			M_AXI_AWCACHE,
		output	wire [2 : 0]			M_AXI_AWPROT,
		output	wire [3 : 0]			M_AXI_AWQOS,
		output	wire				M_AXI_AWVALID,
		input	wire				M_AXI_AWREADY,
		output	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_WDATA,
		output	wire [(C_S_AXI_DATA_WIDTH/8)-1 : 0] M_AXI_WSTRB,
		output	wire				M_AXI_WLAST,
		output	wire				M_AXI_WVALID,
		input	wire				M_AXI_WREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_BID,
		input	wire [1 : 0]			M_AXI_BRESP,
		input	wire				M_AXI_BVALID,
		output	wire				M_AXI_BREADY,
		output	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_ARID,
		output	wire [C_S_AXI_ADDR_WIDTH-1 : 0]	M_AXI_ARADDR,
		output	wire [7 : 0]			M_AXI_ARLEN,
		output	wire [2 : 0]			M_AXI_ARSIZE,
		output	wire [1 : 0]			M_AXI_ARBURST,
		output	wire				M_AXI_ARLOCK,
		output	wire [3 : 0]			M_AXI_ARCACHE,
		output	wire [2 : 0]			M_AXI_ARPROT,
		output	wire [3 : 0]			M_AXI_ARQOS,
		output	wire				M_AXI_ARVALID,
		input	wire				M_AXI_ARREADY,
		input	wire [C_S_AXI_ID_WIDTH-1 : 0]	M_AXI_RID,
		input	wire [C_S_AXI_DATA_WIDTH-1 : 0]	M_AXI_RDATA,
		input	wire [1 : 0]			M_AXI_RRESP,
		input	wire				M_AXI_RLAST,
		input	wire				M_AXI_RVALID,
		output	wire				M_AXI_RREADY
	);

	// Local parameters
	localparam integer FIFO_DEPTH = 1 << LGFIFO;
	localparam integer FIFO_ADDR_WIDTH = LGFIFO;
	localparam integer FFS_STAGES = XCLOCK_FFS;

	// Reset synchronization
	reg [FFS_STAGES-1:0] m_reset_sync;
	always @(posedge M_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			m_reset_sync <= {FFS_STAGES{1'b0}};
		else
			m_reset_sync <= {m_reset_sync[FFS_STAGES-2:0], 1'b1};
	end
	assign M_AXI_ARESETN = m_reset_sync[FFS_STAGES-1];

	// AW channel: S -> M
	reg [C_S_AXI_ID_WIDTH-1:0] aw_fifo_id [0:FIFO_DEPTH-1];
	reg [C_S_AXI_ADDR_WIDTH-1:0] aw_fifo_addr [0:FIFO_DEPTH-1];
	reg [7:0] aw_fifo_len [0:FIFO_DEPTH-1];
	reg [2:0] aw_fifo_size [0:FIFO_DEPTH-1];
	reg [1:0] aw_fifo_burst [0:FIFO_DEPTH-1];
	reg aw_fifo_lock [0:FIFO_DEPTH-1];
	reg [3:0] aw_fifo_cache [0:FIFO_DEPTH-1];
	reg [2:0] aw_fifo_prot [0:FIFO_DEPTH-1];
	reg [3:0] aw_fifo_qos [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] aw_wr_ptr, aw_rd_ptr;
	wire aw_full = (aw_wr_ptr[FIFO_ADDR_WIDTH] != aw_rd_ptr[FIFO_ADDR_WIDTH]) && 
	               (aw_wr_ptr[FIFO_ADDR_WIDTH-1:0] == aw_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
	wire aw_empty = (aw_wr_ptr == aw_rd_ptr);
	wire aw_wr_en = S_AXI_AWVALID && S_AXI_AWREADY;
	wire aw_rd_en = M_AXI_AWVALID && M_AXI_AWREADY;
	assign S_AXI_AWREADY = !aw_full;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			aw_wr_ptr <= 0;
		else if (aw_wr_en)
			aw_wr_ptr <= aw_wr_ptr + 1;
	end

	always @(posedge S_AXI_ACLK) begin
		if (aw_wr_en) begin
			aw_fifo_id[aw_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWID;
			aw_fifo_addr[aw_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWADDR;
			aw_fifo_len[aw_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWLEN;
			aw_fifo_size[aw_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWSIZE;
			aw_fifo_burst[aw_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWBURST;
			aw_fifo_lock[aw_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWLOCK;
			aw_fifo_cache[aw_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWCACHE;
			aw_fifo_prot[aw_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWPROT;
			aw_fifo_qos[aw_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_AWQOS;
		end
	end

	// AW read side in M clock domain
	reg [C_S_AXI_ID_WIDTH-1:0] aw_rd_id;
	reg [C_S_AXI_ADDR_WIDTH-1:0] aw_rd_addr;
	reg [7:0] aw_rd_len;
	reg [2:0] aw_rd_size;
	reg [1:0] aw_rd_burst;
	reg aw_rd_lock;
	reg [3:0] aw_rd_cache;
	reg [2:0] aw_rd_prot;
	reg [3:0] aw_rd_qos;
	reg aw_rd_valid;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			aw_rd_ptr <= 0;
			aw_rd_valid <= 1'b0;
		end else begin
			if (aw_rd_en) begin
				aw_rd_ptr <= aw_rd_ptr + 1;
			end
			if (!aw_empty) begin
				aw_rd_id <= aw_fifo_id[aw_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				aw_rd_addr <= aw_fifo_addr[aw_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				aw_rd_len <= aw_fifo_len[aw_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				aw_rd_size <= aw_fifo_size[aw_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				aw_rd_burst <= aw_fifo_burst[aw_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				aw_rd_lock <= aw_fifo_lock[aw_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				aw_rd_cache <= aw_fifo_cache[aw_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				aw_rd_prot <= aw_fifo_prot[aw_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				aw_rd_qos <= aw_fifo_qos[aw_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				aw_rd_valid <= 1'b1;
			end else if (aw_rd_en) begin
				aw_rd_valid <= 1'b0;
			end
		end
	end

	assign M_AXI_AWID = aw_rd_id;
	assign M_AXI_AWADDR = aw_rd_addr;
	assign M_AXI_AWLEN = aw_rd_len;
	assign M_AXI_AWSIZE = aw_rd_size;
	assign M_AXI_AWBURST = aw_rd_burst;
	assign M_AXI_AWLOCK = aw_rd_lock;
	assign M_AXI_AWCACHE = aw_rd_cache;
	assign M_AXI_AWPROT = aw_rd_prot;
	assign M_AXI_AWQOS = aw_rd_qos;
	assign M_AXI_AWVALID = aw_rd_valid;

	// W channel: S -> M
	reg [C_S_AXI_DATA_WIDTH-1:0] w_fifo_data [0:FIFO_DEPTH-1];
	reg [(C_S_AXI_DATA_WIDTH/8)-1:0] w_fifo_strb [0:FIFO_DEPTH-1];
	reg w_fifo_last [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] w_wr_ptr, w_rd_ptr;
	wire w_full = (w_wr_ptr[FIFO_ADDR_WIDTH] != w_rd_ptr[FIFO_ADDR_WIDTH]) && 
	               (w_wr_ptr[FIFO_ADDR_WIDTH-1:0] == w_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
	wire w_empty = (w_wr_ptr == w_rd_ptr);
	wire w_wr_en = S_AXI_WVALID && S_AXI_WREADY;
	wire w_rd_en = M_AXI_WVALID && M_AXI_WREADY;
	assign S_AXI_WREADY = !w_full;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			w_wr_ptr <= 0;
		else if (w_wr_en)
			w_wr_ptr <= w_wr_ptr + 1;
	end

	always @(posedge S_AXI_ACLK) begin
		if (w_wr_en) begin
			w_fifo_data[w_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_WDATA;
			w_fifo_strb[w_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_WSTRB;
			w_fifo_last[w_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_WLAST;
		end
	end

	// W read side in M clock domain
	reg [C_S_AXI_DATA_WIDTH-1:0] w_rd_data;
	reg [(C_S_AXI_DATA_WIDTH/8)-1:0] w_rd_strb;
	reg w_rd_last;
	reg w_rd_valid;
	reg w_rd_valid_d1;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			w_rd_ptr <= 0;
			w_rd_valid <= 1'b0;
			w_rd_valid_d1 <= 1'b0;
		end else begin
			if (w_rd_en) begin
				w_rd_ptr <= w_rd_ptr + 1;
			end
			if (!w_empty) begin
				w_rd_data <= w_fifo_data[w_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				w_rd_strb <= w_fifo_strb[w_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				w_rd_last <= w_fifo_last[w_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				w_rd_valid <= 1'b1;
			end else if (w_rd_en) begin
				w_rd_valid <= 1'b0;
			end
			w_rd_valid_d1 <= w_rd_valid;
		end
	end

	// Master write data is held one extra M_AXI clock before M_AXI_WVALID
	assign M_AXI_WDATA = w_rd_data;
	assign M_AXI_WSTRB = w_rd_strb;
	assign M_AXI_WLAST = w_rd_last;
	assign M_AXI_WVALID = w_rd_valid_d1;

	// B channel: M -> S
	reg [C_S_AXI_ID_WIDTH-1:0] b_fifo_id [0:FIFO_DEPTH-1];
	reg [1:0] b_fifo_resp [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] b_wr_ptr, b_rd_ptr;
	wire b_full = (b_wr_ptr[FIFO_ADDR_WIDTH] != b_rd_ptr[FIFO_ADDR_WIDTH]) && 
	               (b_wr_ptr[FIFO_ADDR_WIDTH-1:0] == b_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
	wire b_empty = (b_wr_ptr == b_rd_ptr);
	wire b_wr_en = M_AXI_BVALID && M_AXI_BREADY;
	wire b_rd_en = S_AXI_BVALID && S_AXI_BREADY;
	assign M_AXI_BREADY = !b_full;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN)
			b_wr_ptr <= 0;
		else if (b_wr_en)
			b_wr_ptr <= b_wr_ptr + 1;
	end

	always @(posedge M_AXI_ACLK) begin
		if (b_wr_en) begin
			b_fifo_id[b_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= M_AXI_BID;
			b_fifo_resp[b_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= M_AXI_BRESP;
		end
	end

	// B read side in S clock domain
	reg [C_S_AXI_ID_WIDTH-1:0] b_rd_id;
	reg [1:0] b_rd_resp;
	reg b_rd_valid;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			b_rd_ptr <= 0;
			b_rd_valid <= 1'b0;
		end else begin
			if (b_rd_en) begin
				b_rd_ptr <= b_rd_ptr + 1;
			end
			if (!b_empty) begin
				b_rd_id <= b_fifo_id[b_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				b_rd_resp <= b_fifo_resp[b_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				b_rd_valid <= 1'b1;
			end else if (b_rd_en) begin
				b_rd_valid <= 1'b0;
			end
		end
	end

	assign S_AXI_BID = b_rd_id;
	assign S_AXI_BRESP = b_rd_resp;
	assign S_AXI_BVALID = b_rd_valid;

	// AR channel: S -> M
	reg [C_S_AXI_ID_WIDTH-1:0] ar_fifo_id [0:FIFO_DEPTH-1];
	reg [C_S_AXI_ADDR_WIDTH-1:0] ar_fifo_addr [0:FIFO_DEPTH-1];
	reg [7:0] ar_fifo_len [0:FIFO_DEPTH-1];
	reg [2:0] ar_fifo_size [0:FIFO_DEPTH-1];
	reg [1:0] ar_fifo_burst [0:FIFO_DEPTH-1];
	reg ar_fifo_lock [0:FIFO_DEPTH-1];
	reg [3:0] ar_fifo_cache [0:FIFO_DEPTH-1];
	reg [2:0] ar_fifo_prot [0:FIFO_DEPTH-1];
	reg [3:0] ar_fifo_qos [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] ar_wr_ptr, ar_rd_ptr;
	wire ar_full = (ar_wr_ptr[FIFO_ADDR_WIDTH] != ar_rd_ptr[FIFO_ADDR_WIDTH]) && 
	               (ar_wr_ptr[FIFO_ADDR_WIDTH-1:0] == ar_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
	wire ar_empty = (ar_wr_ptr == ar_rd_ptr);
	wire ar_wr_en = S_AXI_ARVALID && S_AXI_ARREADY;
	wire ar_rd_en = M_AXI_ARVALID && M_AXI_ARREADY;
	assign S_AXI_ARREADY = !ar_full;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN)
			ar_wr_ptr <= 0;
		else if (ar_wr_en)
			ar_wr_ptr <= ar_wr_ptr + 1;
	end

	always @(posedge S_AXI_ACLK) begin
		if (ar_wr_en) begin
			ar_fifo_id[ar_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARID;
			ar_fifo_addr[ar_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARADDR;
			ar_fifo_len[ar_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARLEN;
			ar_fifo_size[ar_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARSIZE;
			ar_fifo_burst[ar_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARBURST;
			ar_fifo_lock[ar_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARLOCK;
			ar_fifo_cache[ar_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARCACHE;
			ar_fifo_prot[ar_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARPROT;
			ar_fifo_qos[ar_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= S_AXI_ARQOS;
		end
	end

	// AR read side in M clock domain
	reg [C_S_AXI_ID_WIDTH-1:0] ar_rd_id;
	reg [C_S_AXI_ADDR_WIDTH-1:0] ar_rd_addr;
	reg [7:0] ar_rd_len;
	reg [2:0] ar_rd_size;
	reg [1:0] ar_rd_burst;
	reg ar_rd_lock;
	reg [3:0] ar_rd_cache;
	reg [2:0] ar_rd_prot;
	reg [3:0] ar_rd_qos;
	reg ar_rd_valid;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN) begin
			ar_rd_ptr <= 0;
			ar_rd_valid <= 1'b0;
		end else begin
			if (ar_rd_en) begin
				ar_rd_ptr <= ar_rd_ptr + 1;
			end
			if (!ar_empty) begin
				ar_rd_id <= ar_fifo_id[ar_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				ar_rd_addr <= ar_fifo_addr[ar_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				ar_rd_len <= ar_fifo_len[ar_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				ar_rd_size <= ar_fifo_size[ar_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				ar_rd_burst <= ar_fifo_burst[ar_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				ar_rd_lock <= ar_fifo_lock[ar_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				ar_rd_cache <= ar_fifo_cache[ar_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				ar_rd_prot <= ar_fifo_prot[ar_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				ar_rd_qos <= ar_fifo_qos[ar_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				ar_rd_valid <= 1'b1;
			end else if (ar_rd_en) begin
				ar_rd_valid <= 1'b0;
			end
		end
	end

	assign M_AXI_ARID = ar_rd_id;
	assign M_AXI_ARADDR = ar_rd_addr;
	assign M_AXI_ARLEN = ar_rd_len;
	assign M_AXI_ARSIZE = ar_rd_size;
	assign M_AXI_ARBURST = ar_rd_burst;
	assign M_AXI_ARLOCK = ar_rd_lock;
	assign M_AXI_ARCACHE = ar_rd_cache;
	assign M_AXI_ARPROT = ar_rd_prot;
	assign M_AXI_ARQOS = ar_rd_qos;
	assign M_AXI_ARVALID = ar_rd_valid;

	// R channel: M -> S
	reg [C_S_AXI_ID_WIDTH-1:0] r_fifo_id [0:FIFO_DEPTH-1];
	reg [C_S_AXI_DATA_WIDTH-1:0] r_fifo_data [0:FIFO_DEPTH-1];
	reg [1:0] r_fifo_resp [0:FIFO_DEPTH-1];
	reg r_fifo_last [0:FIFO_DEPTH-1];
	reg [FIFO_ADDR_WIDTH:0] r_wr_ptr, r_rd_ptr;
	wire r_full = (r_wr_ptr[FIFO_ADDR_WIDTH] != r_rd_ptr[FIFO_ADDR_WIDTH]) && 
	               (r_wr_ptr[FIFO_ADDR_WIDTH-1:0] == r_rd_ptr[FIFO_ADDR_WIDTH-1:0]);
	wire r_empty = (r_wr_ptr == r_rd_ptr);
	wire r_wr_en = M_AXI_RVALID && M_AXI_RREADY;
	wire r_rd_en = S_AXI_RVALID && S_AXI_RREADY;
	assign M_AXI_RREADY = !r_full;

	always @(posedge M_AXI_ACLK or negedge M_AXI_ARESETN) begin
		if (!M_AXI_ARESETN)
			r_wr_ptr <= 0;
		else if (r_wr_en)
			r_wr_ptr <= r_wr_ptr + 1;
	end

	always @(posedge M_AXI_ACLK) begin
		if (r_wr_en) begin
			r_fifo_id[r_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= M_AXI_RID;
			r_fifo_data[r_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= M_AXI_RDATA;
			r_fifo_resp[r_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= M_AXI_RRESP;
			r_fifo_last[r_wr_ptr[FIFO_ADDR_WIDTH-1:0]] <= M_AXI_RLAST;
		end
	end

	// R read side in S clock domain
	reg [C_S_AXI_ID_WIDTH-1:0] r_rd_id;
	reg [C_S_AXI_DATA_WIDTH-1:0] r_rd_data;
	reg [1:0] r_rd_resp;
	reg r_rd_last;
	reg r_rd_valid;

	always @(posedge S_AXI_ACLK or negedge S_AXI_ARESETN) begin
		if (!S_AXI_ARESETN) begin
			r_rd_ptr <= 0;
			r_rd_valid <= 1'b0;
		end else begin
			if (r_rd_en) begin
				r_rd_ptr <= r_rd_ptr + 1;
			end
			if (!r_empty) begin
				r_rd_id <= r_fifo_id[r_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				r_rd_data <= r_fifo_data[r_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				r_rd_resp <= r_fifo_resp[r_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				r_rd_last <= r_fifo_last[r_rd_ptr[FIFO_ADDR_WIDTH-1:0]];
				r_rd_valid <= 1'b1;
			end else if (r_rd_en) begin
				r_rd_valid <= 1'b0;
			end
		end
	end

	assign S_AXI_RID = r_rd_id;
	assign S_AXI_RDATA = r_rd_data;
	assign S_AXI_RRESP = r_rd_resp;
	assign S_AXI_RLAST = r_rd_last;
	assign S_AXI_RVALID = r_rd_valid;

endmodule
